import java.io.*;
import java.util.*;

class Solution {
    private long[] generateSums(int[] nums, int start, int len) {
        int size = 1 << len;
        long[] sums = new long[size];
        for (int mask = 1; mask < size; mask++) {
            int bit = mask & -mask;
            int idx = Integer.numberOfTrailingZeros(bit);
            sums[mask] = sums[mask ^ bit] + nums[start + idx];
        }
        return sums;
    }

    private int lowerBound(long[] arr, long target) {
        int lo = 0, hi = arr.length;
        while (lo < hi) {
            int mid = lo + (hi - lo) / 2;
            if (arr[mid] < target) lo = mid + 1;
            else hi = mid;
        }
        return lo;
    }

    public int minAbsDifference(int[] nums, int goal) {
        long maxSum = 0, minSum = 0;
        for (int x : nums) {
            if (x > 0) maxSum += x;
            else if (x < 0) minSum += x;
        }
        if (goal > maxSum) return (int)(goal - maxSum);
        if (goal < minSum) return (int)(minSum - goal);

        int n = nums.length;
        int mid = n / 2;
        long[] left = generateSums(nums, 0, mid);
        long[] right = generateSums(nums, mid, n - mid);
        Arrays.sort(left);

        long best = Math.abs((long) goal);
        for (long s : right) {
            long target = (long) goal - s;
            int i = lowerBound(left, target);
            if (i < left.length) best = Math.min(best, Math.abs(s + left[i] - goal));
            if (i > 0) best = Math.min(best, Math.abs(s + left[i - 1] - goal));
            if (best == 0) return 0;
        }
        return (int) best;
    }
}

