static vector<long long> generateSums(const vector<int>& nums, int start, int len) {
    const int size = 1 << len;
    vector<long long> sums(size, 0);
    for (int mask = 1; mask < size; ++mask) {
        int bit = mask & -mask;
        int idx = __builtin_ctz(bit);
        sums[mask] = sums[mask ^ bit] + nums[start + idx];
    }
    return sums;
}

static int minAbsDifference(vector<int>& nums, int goal) {
    long long maxSum = 0, minSum = 0;
    for (int x : nums) {
        if (x > 0) maxSum += x;
        else if (x < 0) minSum += x;
    }
    if (goal > maxSum) return (int)(goal - maxSum);
    if (goal < minSum) return (int)(minSum - goal);

    int n = (int)nums.size();
    int mid = n / 2;
    vector<long long> left = generateSums(nums, 0, mid);
    vector<long long> right = generateSums(nums, mid, n - mid);
    sort(left.begin(), left.end());

    long long best = llabs((long long)goal);
    for (long long s : right) {
        long long target = (long long)goal - s;
        auto it = lower_bound(left.begin(), left.end(), target);
        if (it != left.end()) best = min(best, llabs(s + *it - goal));
        if (it != left.begin()) {
            --it;
            best = min(best, llabs(s + *it - goal));
        }
        if (best == 0) return 0;
    }
    return (int)best;
}

static vector<long long> extractIntegers(const string& line) {
    vector<long long> values;
    for (size_t i = 0; i < line.size();) {
        if (line[i] == '-' || isdigit((unsigned char)line[i])) {
            size_t j = i;
            if (line[j] == '-') ++j;
            if (j < line.size() && isdigit((unsigned char)line[j])) {
                long long value = 0;
                bool neg = (line[i] == '-');
                while (j < line.size() && isdigit((unsigned char)line[j])) {
                    value = value * 10 + (line[j] - '0');
                    ++j;
