static int compare_ll(const void* a, const void* b) {
    long long x = *(const long long*)a;
    long long y = *(const long long*)b;
    return (x > y) - (x < y);
}

static void generate_sums(const int* nums, int start, int len, long long* sums) {
    int size = 1 << len;
    sums[0] = 0;
    for (int mask = 1; mask < size; ++mask) {
        int bit = mask & -mask;
        int idx = __builtin_ctz((unsigned)bit);
        sums[mask] = sums[mask ^ bit] + nums[start + idx];
    }
}

static int lower_bound(const long long* arr, int n, long long target) {
    int lo = 0, hi = n;
    while (lo < hi) {
        int mid = lo + (hi - lo) / 2;
        if (arr[mid] < target) lo = mid + 1;
        else hi = mid;
    }
    return lo;
}

int minAbsDifference(int* nums, int numsSize, int goal) {
    long long maxSum = 0, minSum = 0;
    for (int i = 0; i < numsSize; ++i) {
        if (nums[i] > 0) maxSum += nums[i];
        else if (nums[i] < 0) minSum += nums[i];
    }
    if ((long long)goal > maxSum) return (int)((long long)goal - maxSum);
    if ((long long)goal < minSum) return (int)(minSum - (long long)goal);

    int mid = numsSize / 2;
    int leftSize = 1 << mid;
    int rightLen = numsSize - mid;
    int rightSize = 1 << rightLen;

    long long* left = (long long*)malloc((size_t)leftSize * sizeof(long long));
    long long* right = (long long*)malloc((size_t)rightSize * sizeof(long long));
    if (!left || !right) exit(EXIT_FAILURE);

    generate_sums(nums, 0, mid, left);
    generate_sums(nums, mid, rightLen, right);
    qsort(left, leftSize, sizeof(long long), compare_ll);

    long long best = llabs((long long)goal);
    for (int i = 0; i < rightSize; ++i) {
        long long s = right[i];
        long long target = (long long)goal - s;
        int pos = lower_bound(left, leftSize, target);
        if (pos < leftSize) {
            long long diff = llabs(s + left[pos] - goal);
            if (diff < best) best = diff;
        }
        if (pos > 0) {
            long long diff = llabs(s + left[pos - 1] - goal);
            if (diff < best) best = diff;
        }
        if (best == 0) break;
    }

    free(left);
    free(right);
    return (int)best;
}

